(window.SITE_PRS=window.SITE_PRS||{})["mayteio"]=[{"id":"ws1","title":"Product: Workflows · workflows","area":"Product: Workflows","agg":{"prs_n":174,"deepread_n":12,"tier_counts":{"substantive":111,"major":21,"routine":37,"trivial":5},"points_sum":714.28,"L_mean":1.17,"Q_mean":1.67,"span_days":90,"lines":83004},"prs":[{"number":78136,"tier":"substantive","P":null,"summary":"Adds open rate and CTR columns to workflow email metrics, dividing by tracked sends to avoid understating engagement."},{"number":78208,"tier":"substantive","P":null,"summary":"Workflows API now infers fixed template_id from step type and coerces UUID template references into config.template_uuid, fixing a common authoring error."},{"number":78272,"tier":"major","P":null,"summary":"Programmatic workflow authors can now reference and materialize email templates at save time, matching the web editor's functionality."},{"number":78745,"tier":"major","P":null,"summary":"Fixes SES SNS subscription confirmation so delivery, bounce and complaint events are no longer silently dropped from the ingestion pipeline."},{"number":78805,"tier":"substantive","P":null,"summary":"Adds a Celery task polling AWS SES account reputation verdicts and pushing pushgateway gauges so the workflows team can alert on real SES enforcement status."},{"number":78876,"tier":"major","P":null,"summary":"Auto-wraps html-only workflow emails into an editable design, preventing blank-canvas saves from overwriting real email HTML."},{"number":79512,"tier":"routine","P":4.49,"summary":"Adds multiprocess_mode=\"mostrecent\" to the three SES reputation poller gauges so each celery worker pod exports one up-to-date series instead of per-pid stale copies, stopping the flapping SesReputationPollerStaleWarning alert."},{"number":80639,"tier":"substantive","P":null,"summary":"Auto-opens the AI panel on workflows with pre-attached workflow context, via a reusable scene-context mechanism other products can adopt."},{"number":81114,"tier":"substantive","P":null,"summary":"Workflow delay/wait steps now accept seconds and fractional durations, aligning editor, API and executor schemas and fixing validation of API-created delays."},{"number":81323,"tier":"major","P":null,"summary":"Adds a draft/publish cycle, version history and rollback UI to the workflows web editor, so active workflow edits stage instead of deploying immediately."},{"number":81905,"tier":"major","P":null,"summary":"Improved workflow email editing by replacing the modal with a live, auto-saving editor that integrates seamlessly with the AI panel."},{"number":81966,"tier":"routine","P":null,"summary":"Disables Unlayer's default AI features in the workflows email editor to stop unwanted paid AI credit usage."},{"number":82784,"tier":"routine","P":null,"summary":"Migrates two scoped service JWT implementations onto shared machinery with no behavior change for callers."},{"number":83059,"tier":"substantive","P":4.49,"summary":"Adds optional templated From address/name overrides to workflow email steps, with runtime validation that the rendered address stays on the integration's verified domain and sanitization of the display name."},{"number":83100,"tier":"routine","P":null,"summary":"Adds a nullable cancel_requested_at column to cyclotron_jobs as preparatory schema work for upcoming workflow cancellation code."},{"number":83342,"tier":"substantive","P":null,"summary":"Adds cancel for in-flight workflow runs via a new API endpoint and UI, plus fixes runs stuck showing as running."},{"number":83638,"tier":"substantive","P":null,"summary":"Adds a Stop button and transactional cancellation to halt batch workflow broadcasts mid-enrollment, closing the enqueue-during-cancel race."},{"number":83804,"tier":"major","P":null,"summary":"Fixes masked re-saves wiping legacy plaintext workflow secrets, which silently disabled webhook auth, plus a backfill migration."},{"number":83830,"tier":"substantive","P":null,"summary":"Relabels the workflow email 'Blocked' metric to 'Marked as spam' so SES complaint events no longer mislead users about deliverability."},{"number":84345,"tier":"substantive","P":null,"summary":"Adds a workflow_tasks endpoint so workflows can create and start AI agent tasks, with scoped JWT auth, connector enforcement and dedup."},{"number":85217,"tier":"substantive","P":null,"summary":"Adds save-time validation rejecting off-domain custom sender addresses in workflow email steps, preventing silent fallback to default senders."},{"number":85239,"tier":"substantive","P":null,"summary":"Adds a management command to strip the legacy default@example.com placeholder sender from stored workflow email steps, fixing phantom senders and warnings."},{"number":85511,"tier":"substantive","P":null,"summary":"Adds a flag-gated 'Create AI task' workflow step that starts AI agent tasks with model, repository and MCP connector pickers."},{"number":85681,"tier":"substantive","P":null,"summary":"Reset-to-template on a CDP destination no longer wipes configured event filters, falling back to template defaults only when none exist."},{"number":86731,"tier":"substantive","P":null,"summary":"Binds AI tasks to the Slack thread that triggered them, letting agents read and reply in-thread with reactions and a new step toggle."},{"number":87847,"tier":"major","P":null,"summary":"Splits workflows cancel JWTs onto a dedicated secret so a leaked key from one tier can no longer forge the other's calls."},{"number":87865,"tier":"substantive","P":null,"summary":"Server-side validation now rejects activating a Slack-message workflow trigger without a channel filter, closing bypasses that ran it on every channel."},{"number":88024,"tier":"substantive","P":null,"summary":"Adds a clickable link in workflow logs to jump directly to the AI task, significantly improving usability for workflow authors."},{"number":88244,"tier":"substantive","P":null,"summary":"Adds save-time validation for AI task configurations in workflows, preventing runtime failures due to misconfiguration."},{"number":88642,"tier":"substantive","P":null,"summary":"Fixes Slack workflow triggers for workspaces connected in both regions by mirroring top-level channel messages cross-region via a Celery task."},{"number":90875,"tier":"substantive","P":null,"summary":"Adds a Send test button and modal to the email template library editor, reusing the hog flow test-invocation endpoint."},{"number":90938,"tier":"substantive","P":null,"summary":"Adds a flag-gated \"Run scout\" workflow action with a new dispatch endpoint, idempotent replay, and shared pre-dispatch gates with the manual run path."},{"number":91486,"tier":"major","P":null,"summary":"Fixes workflow auto-save races that caused false conflict banners, button swapping, duplicate schedules firing workflows twice, and stopped workflows resuming sends."},{"number":91572,"tier":"substantive","P":null,"summary":"Workflow test runs now apply the same trigger event/filter/team checks as production for Slack and warehouse triggers, so tests can no longer falsely report success."},{"number":91581,"tier":"substantive","P":null,"summary":"Adds a run-now endpoint to fire schedule-triggered workflows on demand and a hog_flow_id filter to list a workflow's spawned tasks."},{"number":92150,"tier":"substantive","P":null,"summary":"Adds $fbc to person-property preserve lists so browser-captured Meta click timestamps survive trimming, improving ad attribution."},{"number":92152,"tier":"substantive","P":null,"summary":"Meta Ads destination now drops stale (>90-day) ad clicks and stops malformed fbc values from breaking the whole send."},{"number":92281,"tier":"substantive","P":null,"summary":"Adds a Skills picker to the workflow 'Create AI task' node, injecting team skills into the agent prompt at fire time."},{"number":92674,"tier":"substantive","P":null,"summary":"Adds an immutable origin_product tag to workflows plus an API filter so Desktop's Loops can list only workflows it created."},{"number":93177,"tier":"substantive","P":null,"summary":"Adds per-project Django admin overrides for workflow AI task daily limits, letting staff raise or pause limits without changing global defaults."},{"number":93383,"tier":"substantive","P":13.0,"summary":"Lets agents attach a cadence to a schedule-trigger workflow without a blast-radius token, and adds a guard that pauses active schedules whenever a live edit turns a person-less trigger into a batch broadcast or widens batch filters, closing an unconfirmed recurring-send gap."},{"number":94050,"tier":"major","P":null,"summary":"Introduces a mechanism for workflow steps to wait for AI or Scout tasks to reach a terminal status before proceeding."},{"number":94051,"tier":"substantive","P":null,"summary":"AI task and scout steps now wait for agent runs, passing status and result to the next step, behind a default-off flag."},{"number":94113,"tier":"substantive","P":null,"summary":"Redesigns the workflow template picker with step previews, metadata rows, an AI badge, and single-sentence descriptions for readability."},{"number":94119,"tier":"major","P":null,"summary":"Bounds Liquid template rendering with parse/time/memory limits so a tenant template can no longer stall or OOM the shared CDP worker for all teams."},{"number":97290,"tier":"substantive","P":null,"summary":"Workflow steps can now read structured fields from an AI task's output, with schema validation and warnings for malformed or truncated output."},{"number":97303,"tier":"substantive","P":null,"summary":"Lets workflow authors map AI task output fields (e.g. output.verdict) into workflow variables, deriving the schema from mappings at dispatch."},{"number":97307,"tier":"substantive","P":null,"summary":"Adds a 7-day trigger volume estimate and AI task-limit warning to the workflow trigger panel, behind a default-off flag."},{"number":97591,"tier":"major","P":13.0,"summary":"Clamps the cyclotron transition_count and janitor_touch_count increments with LEAST at all 13 sites so a saturated SMALLINT row can no longer abort a batch claim and stall an entire queue, and adds a churn metric to surface retry-looping jobs before they saturate."},{"number":97639,"tier":"trivial","P":null,"summary":"Rewords the workflow cohort split warning to describe relative-weight routing instead of the outdated remainder-to-last-cohort behavior."},{"number":98383,"tier":"substantive","P":4.49,"summary":"This PR exposes the previously staff-only per-workflow and per-project daily AI task limits in Settings > Workflows with a 5x self-serve ceiling, letting project admins raise, lower, or zero their own limits without a support request."},{"number":99081,"tier":"substantive","P":null,"summary":"Meta Ads destination now falls back to the $fbp person property, improving Conversions API match quality for projects using the PostHog SDK."},{"number":99967,"tier":"substantive","P":null,"summary":"Adds a Loop tag and filter to the Workflows Type column plus a bridge scene deep-linking loop workflows into PostHog Desktop."},{"number":100315,"tier":"routine","P":null,"summary":"Adds a Prometheus counter tracking how awaited workflow steps finish (completed, failed, cancelled, timed out) for Grafana observability."},{"number":100805,"tier":"routine","P":null,"summary":"Adds an internal histogram measuring how long awaited workflow steps wait, aiding on-call diagnosis of slow or timed-out steps."},{"number":100965,"tier":"major","P":null,"summary":"Correctly configures the subscription matcher to read internal workflow events from the correct Kafka cluster, resolving production timeouts."},{"number":101217,"tier":"substantive","P":null,"summary":"Adds an experiment-gated PostHog AI composer that drafts new workflows from a prompt, replacing the template modal for test-variant users."},{"number":101477,"tier":"substantive","P":null,"summary":"Replaces the Kafka-based workflow step-resume wake with an authenticated CDP API call, making AI task step resumption more reliable."},{"number":101857,"tier":"substantive","P":null,"summary":"Adds an experiment-gated PostHog AI composer for creating email templates in workflows, with template picking and editor handoff."},{"number":102211,"tier":"substantive","P":null,"summary":"Email template editor now reloads on external edits, preventing stale saves from overwriting changes made elsewhere."},{"number":102212,"tier":"substantive","P":null,"summary":"Moves the AI-first create composer and handoff logic into a shared, parameterized shell so other entities can reuse it, plus a small id-lookup fix."},{"number":102248,"tier":"substantive","P":null,"summary":"GitHub workflow triggers now match repository names case-insensitively, fixing triggers that silently never fired on a case mismatch."},{"number":107597,"tier":"substantive","P":null,"summary":"Introduces a workflows facade and routes all external callers through it, enabling future CI isolation with no user-visible change."},{"number":107724,"tier":"substantive","P":null,"summary":"Adds a batched last_run field to workflow list/detail responses for loop workflows, enabling Desktop to show real run status instead of \"Never ran\"."},{"number":107725,"tier":"substantive","P":null,"summary":"Fixes desktop loops list to show last run time and failing status for workflow-backed loops by mapping last_run from workflow responses."},{"number":108183,"tier":"routine","P":null,"summary":"Removes the obsolete CDP destinations incident replay banner, its kea logic, tests and flag key, since the 30-day replay window has closed."},{"number":108193,"tier":"major","P":null,"summary":"Prevents CDP destination workers from crashing during transient DNS failures by treating ENOTFOUND errors as retriable, improving webhook delivery reliability."},{"number":108318,"tier":"routine","P":null,"summary":"Adds TypedDict contracts for the SES and Twilio workflows facade; type annotations only, no runtime or user-visible change."},{"number":108408,"tier":"routine","P":null,"summary":"Seals 12 workflows reverse accessors to Team/User via related_name='+', a no-op migration advancing the workflows isolation plan."},{"number":108476,"tier":"routine","P":null,"summary":"Routes three small workflows views through the facade layer, removing internal imports to unblock CI contract-check; no user-visible change."},{"number":108488,"tier":"substantive","P":null,"summary":"Moves the workflow template viewset behind a facade and fixes the template chooser to keep the curated file order instead of process-dependent sorting."},{"number":109047,"tier":"routine","P":null,"summary":"Moves workflows step-validation checks behind the facade layer, removing five import-ignore entries to enable CI skipping; no user-visible change."},{"number":109398,"tier":"substantive","P":null,"summary":"Routes workflows blast-radius counts through a new facade for CI skipping, and carries a fix unblocking backend PRs in the merge queue."},{"number":109399,"tier":"substantive","P":null,"summary":"Refactors email health logic into a facade layer to improve code structure and allow CI to skip unnecessary checks."},{"number":109400,"tier":"routine","P":null,"summary":"Moves workflows schedule CRUD and due-schedule processing behind a facade/service layer, with no user-visible behavior change."},{"number":109406,"tier":"routine","P":null,"summary":"Refactors workflows revisions, proposals and optimization behind a facade with no behavior change, cutting CI import ignores."},{"number":109407,"tier":"routine","P":null,"summary":"Moves workflows email design/template reads behind a facade to shrink CI test scope, with no user-visible behavior change."},{"number":109408,"tier":"routine","P":null,"summary":"Moves workflows message-asset queries and public template routing into the product package behind a facade, with no user-visible change."},{"number":109843,"tier":"substantive","P":null,"summary":"Adds a project-wide frequency cap for marketing messages across all workflows, with settings UI, Valkey-based counting, and metrics."},{"number":110082,"tier":"routine","P":null,"summary":"Adds two nullable frequency-cap columns to the workflows team config table as a prerequisite for a later feature; no behavior yet."},{"number":110124,"tier":"routine","P":null,"summary":"Moves workflows batch job endpoints behind a facade with no behavior change, as one slice of a larger refactor."},{"number":110630,"tier":"routine","P":null,"summary":"Moves the workflows proposal lifecycle behind the facade with no user-visible change, part of a larger test-isolation migration."},{"number":110632,"tier":"substantive","P":null,"summary":"Routes the workflow update write path through the facade, enabling test isolation and fixing concurrency edge cases in updates."},{"number":113123,"tier":"routine","P":null,"summary":"Moves workflows create/delete/edit/publish/discard logic behind a facade with no behavior change, enabling narrower test scope."},{"number":113179,"tier":"routine","P":null,"summary":"Moves workflows retrieve onto a facade/Workflow contract with no user-visible change, as one slice of a larger refactor."},{"number":113187,"tier":"routine","P":null,"summary":"Moves the workflows list endpoint behind the facade/service layer with no user-visible change, improving test isolation."},{"number":113258,"tier":"routine","P":null,"summary":"Refactors workflow serializers to validate-only and routes writes through services, decoupling the facade from view internals with no user-visible change."},{"number":113264,"tier":"routine","P":null,"summary":"Refactors workflows views to read a frozen WorkflowRef via the facade instead of get_object(), decoupling views from internals with no user-visible change."},{"number":113268,"tier":"substantive","P":null,"summary":"Adds a Workflows endpoint to import people from an uploaded CSV into a cohort, creating/updating persons and properties."},{"number":113270,"tier":"routine","P":null,"summary":"Routes workflow activity logging and bulk delete/email resume through the facade, with no user-visible behavior change."},{"number":113283,"tier":"routine","P":null,"summary":"Refactors workflows write views to validate edits against a frozen contract instead of the HogFlow model row, with no user-visible change."},{"number":113288,"tier":"substantive","P":null,"summary":"Broadcast list upload now creates or updates people from CSV rows, turning columns into person properties, behind a feature flag."},{"number":113315,"tier":"routine","P":null,"summary":"Internal refactor moving workflow proposal approval and enums off the model into facade/services, with no user-visible or schema change."},{"number":113470,"tier":"substantive","P":null,"summary":"Removes feature flag and env gates so the Slack workflow trigger is available to all projects."},{"number":113772,"tier":"routine","P":2.19,"summary":"Mechanically re-routes the workflows viewset's `HogFlow` import through a new facade re-export and adds a `(\"workflows\", \"HogFlow\")` entry to the watched-models allowance so workflows PRs can skip the full backend suite, with no user-visible behavior change."},{"number":113774,"tier":"routine","P":null,"summary":"Enables test isolation for the workflows product so its PRs run only workflows tests instead of the full Django suite."},{"number":114006,"tier":"major","P":null,"summary":"Adds a feature-flagged 'Classify with AI' workflow action letting users route on model-chosen categories, with new internal route and CDP function."},{"number":115358,"tier":"substantive","P":null,"summary":"Refreshes global workflow templates, adds AI templates, and improves the template picker and survey alert logic for users."},{"number":115944,"tier":"routine","P":null,"summary":"Makes the AI-first trial banner dismissible and less prominent across three workflow screens, adding persisted dismissal and a close event."},{"number":115952,"tier":"substantive","P":null,"summary":"Backs the workflow email editor's Uploads tab with a shared media library, adding upload, search, and soft-delete via the media API."},{"number":116188,"tier":"substantive","P":null,"summary":"Adds the hog_flow:write key scope, transactional-email JWT audience/secret, and a cdp-api client that nothing calls yet."},{"number":116200,"tier":"substantive","P":null,"summary":"Cohort lookup failures in workflows now retry then abort the run instead of wrongly routing people down the 'not in cohort' branch."},{"number":116906,"tier":"substantive","P":null,"summary":"Adds UI to review, publish and discard staged destination drafts, matching existing workflows behavior for MCP-edited destinations."},{"number":116922,"tier":"substantive","P":null,"summary":"Adds a cohort membership trigger type to Workflows (model, validation, picker) behind a flag, though nothing fires it yet."},{"number":116951,"tier":"major","P":null,"summary":"Implements real-time workflow triggers based on changes in user cohort membership, allowing for event-driven automation."},{"number":117007,"tier":"substantive","P":null,"summary":"Blocks deleting or de-realtime-ing cohorts used by active workflows, preventing silent trigger and branch breakage."},{"number":117013,"tier":"substantive","P":null,"summary":"Cohort editor now sends filterTestAccounts in the save payload, so the internal/test-user filter toggle actually persists."},{"number":117032,"tier":"substantive","P":null,"summary":"Adds a Frequency setting to cohort triggers so workflows can limit how often a person re-enters, matching existing event triggers."},{"number":117662,"tier":"substantive","P":null,"summary":"Lets workflow authors target realtime behavioral cohorts in batch audiences by reading live Postgres membership, behind a feature flag."},{"number":117663,"tier":"major","P":12.13,"summary":"Adds an `api` trigger type and a `transactional_emails` origin product plus facade/service functions that create and version one-step email workflows, letting the messaging product back transactional emails with real workflows instead of throwaway flows."},{"number":117673,"tier":"major","P":null,"summary":"Adds an authenticated CDP route that queues transactional email workflow runs, enabling customer-facing transactional email sends with quota checks and scoped JWT auth."},{"number":117704,"tier":"substantive","P":null,"summary":"Workflows batch runs can now target a still-calculating realtime cohort, parking until the cohort's readiness signal resumes them."},{"number":117708,"tier":"substantive","P":null,"summary":"Adds a modal listing workflows blocking a cohort delete/edit, plus a new blocking_workflows endpoint and used_in workflows block."},{"number":117721,"tier":"trivial","P":null,"summary":"Adds shrink-0 to the workflow email pause banner so it keeps its natural height instead of overflowing."},{"number":117726,"tier":"substantive","P":null,"summary":"Adds template library UI to make email templates transactional, showing API example, sends, metrics and versions."},{"number":117740,"tier":"substantive","P":null,"summary":"Teaches the CDP batch resolver to page a realtime cohort's members from Postgres, enabling batch sends to target realtime cohorts."},{"number":117766,"tier":"substantive","P":null,"summary":"Removes the workflow-run-scout-action flag so every project can add the Run scout step in the workflow builder."},{"number":117870,"tier":"substantive","P":null,"summary":"Workflow pickers now enforce realtime cohorts as the sole audience condition, hiding add-condition and clearing extras to prevent save-time 400 errors."},{"number":118407,"tier":"major","P":7.82,"summary":"The cohort-membership trigger consumer now parses a whole Kafka batch and loads each team's workflows once per batch instead of once per message, fixing a Node heap exhaustion that crashed the prod-us consumer and stalled cohort-triggered workflows."},{"number":118444,"tier":"substantive","P":null,"summary":"Adds a park/resume mechanism so CDP batch resolvers wait for a realtime cohort to finish before broadcasting."},{"number":118447,"tier":"major","P":null,"summary":"Locks cohort criteria edits when active workflows use the cohort, preventing duplicate workflow entries and fixing an incident."},{"number":118456,"tier":"substantive","P":null,"summary":"Fixes workflow emails so suppressed cc/bcc recipients are dropped and delivery continues instead of skipping the whole email."},{"number":118530,"tier":"routine","P":null,"summary":"Adds a partial index on (team_id, parent_run_id) to speed up batch resolver job lookups in the cyclotron queue."},{"number":118624,"tier":"substantive","P":null,"summary":"Person's Emails tab now also lists unlinked transactional sends matched by distinct ID or email, improving send visibility."},{"number":118664,"tier":"substantive","P":null,"summary":"Adds a draft/publish flow to transactional email templates so edits autosave to a draft and only go live on publish."},{"number":119400,"tier":"substantive","P":null,"summary":"Workflow/broadcast authors now see when a send waits for a realtime cohort, with auto-refreshing status, disabled buttons on failure, and hidden stale counts."},{"number":120041,"tier":"substantive","P":null,"summary":"Adds a flag-gated 'Add to static cohort' workflow step so builders can record a person into a static cohort during a run."},{"number":120171,"tier":"substantive","P":null,"summary":"Fixes workflow emails showing HTML entities in subjects, plain text and names, and sanitizes mailbox fields against header injection."},{"number":120178,"tier":"substantive","P":null,"summary":"Workflows delays now allow up to 365 days (waits stay capped at 30), with save validation and builder support, unblocking longer lifecycle automations."},{"number":120188,"tier":"routine","P":null,"summary":"Disables Celery retry jitter on the realtime cohort resume task so retries span the full 24h wait instead of ~12h."},{"number":120205,"tier":"substantive","P":null,"summary":"Agents now draft AI emails as editable native Unlayer blocks instead of one raw HTML block, plus a validator fix for false warnings."},{"number":120313,"tier":"substantive","P":null,"summary":"Raises workflow delay ceiling from 30 to 365 days so long lifecycle waits run fully, unblocking Customer.io automation imports."},{"number":120330,"tier":"substantive","P":null,"summary":"Adds a Liquid `currency` filter to CDP worker and frontend preview so imported email templates format money correctly."},{"number":120394,"tier":"trivial","P":null,"summary":"Corrects a permission label and the example send URL host in the transactional email setup UI."},{"number":120429,"tier":"substantive","P":null,"summary":"Cohort-triggered workflows now exit early when a person leaves or rejoins the trigger cohort, making an existing setting work."},{"number":120446,"tier":"substantive","P":null,"summary":"Adds a shared idempotency key store for CDP workflow routes, not yet wired into any route."},{"number":120510,"tier":"substantive","P":null,"summary":"Adds an optional idempotency key to cdp-api's transactional email route so callers can retry without sending duplicate emails."},{"number":121079,"tier":"substantive","P":null,"summary":"Adds editor UI to set a transactional email template's sender name, address and reply-to, with inline validation blocking publish."},{"number":121138,"tier":"substantive","P":3.65,"summary":"Fixes the workflows test panel so it reads the person id from the events query's `person.uuid` column (falling back to `id`), making cohort-based branches test against the real person, with regression tests added."},{"number":121238,"tier":"substantive","P":null,"summary":"Adds flag-gated backend endpoint and service JWT letting Workflows opt a person out of message categories, replacing fragile webhook-based opt-outs."},{"number":121239,"tier":"substantive","P":null,"summary":"Adds a CDP async function and hidden template letting workflows opt a person out of message categories, with later sends skipping them."},{"number":121240,"tier":"substantive","P":null,"summary":"Adds a flag-gated workflow builder step letting users opt a person out of a message category, plus category pagination and step tracking."},{"number":121872,"tier":"routine","P":null,"summary":"Dev-only MailDev email transport now forwards reply-to addresses, letting engineers verify reply-to locally; production behavior unchanged."},{"number":121883,"tier":"trivial","P":2.19,"summary":"Swaps the error-handling badge logic in the workflow step panel so an unset on_error shows \"Continue on error\" (green) and only on_error: 'abort' shows \"Exit on error\" (red), aligning the UI with the executor and selector defaults."},{"number":122133,"tier":"routine","P":null,"summary":"Removes two fully-rolled-out feature flags and their dead code paths in the Workflows broadcast audience and trigger panels."},{"number":122553,"tier":"substantive","P":null,"summary":"Cohort joins/leaves now satisfy workflow conversion goals and waits via $cohort_membership_changed events, with capture spoofing blocked."},{"number":122554,"tier":"substantive","P":null,"summary":"Adds cohort join/leave pickers to workflow conversion goals and wait steps, enabling realtime cohort membership triggers in the editor."},{"number":123310,"tier":"substantive","P":null,"summary":"Adds support for the `unsubscribe_url` Liquid tag in email templates, resolving workflow failures for users utilizing Customer.io templates."},{"number":123314,"tier":"substantive","P":null,"summary":"Message categories gain personal API key/OAuth scopes, resource-level access control and four new MCP tools so agents can manage categories."},{"number":123315,"tier":"substantive","P":null,"summary":"Email editor now accepts the {% unsubscribe_url %} Liquid tag, letting Customer.io-imported templates save and preview without errors."},{"number":123479,"tier":"major","P":null,"summary":"Customer.io imports now store global unsubscribes as the $all opt-out, preventing marketing emails to globally unsubscribed contacts."},{"number":123481,"tier":"major","P":null,"summary":"Fixes duplicate transactional email sends after a Valkey outage by retrying idempotency completion in the background."},{"number":123567,"tier":"substantive","P":null,"summary":"Customer.io import now also pulls suppression lists (bounces, complaints) into the project, protecting sender reputation for migrating teams."},{"number":123882,"tier":"routine","P":null,"summary":"Bare /workflows/<id> links now redirect to the workflow instead of falling back to the list view."},{"number":124104,"tier":"substantive","P":null,"summary":"Reorders Customer.io import so suppressions save before global unsubscribes, preventing timeouts from dropping bounce/spam suppression data."},{"number":124198,"tier":"substantive","P":null,"summary":"Customer.io suppression imports now retain bounce dates, status codes and diagnostics, and backfill earlier imported rows."},{"number":124424,"tier":"substantive","P":null,"summary":"Splits c.io import paging from saving to enable a resumable Temporal job, with no user-visible behavior change."},{"number":124695,"tier":"substantive","P":null,"summary":"Moves the Customer.io import to a background run with per-step progress UI and fixes duplicate emails aborting unsubscribe batches."},{"number":124736,"tier":"substantive","P":null,"summary":"Adds best-effort Node writes of queued/sent/failed transactional email status into the new ClickHouse table, gated behind a feature flag."},{"number":124751,"tier":"substantive","P":null,"summary":"Records skipped, failed, delivered, bounced and complained transactional email statuses in CDP, fixing emails stuck at queued or sent."},{"number":124769,"tier":"substantive","P":null,"summary":"Workflow drafts can now reference realtime cohorts still calculating, with readiness enforced at enable time and clearer progress errors."},{"number":124858,"tier":"routine","P":null,"summary":"Removes the flag-gated in-request Customer.io import path, making the already-rolled-out background import the only flow."},{"number":124979,"tier":"substantive","P":null,"summary":"Adds an optional per-step skip_frequency_cap setting to CDP email steps so marketing sends bypass the project cap while keeping opt-outs."},{"number":125042,"tier":"substantive","P":null,"summary":"Accepts null linkTags on SES click webhooks so workflow email link clicks are no longer dropped from metrics."},{"number":126153,"tier":"trivial","P":2.19,"summary":"Updates the in-app transactional email curl example to use the documented `messaging/send/email/` endpoint with `template.id` and an `Idempotency-Key` header, plus one explanatory bullet, so copied snippets match the docs and SDKs."},{"number":126157,"tier":"substantive","P":null,"summary":"Allows AI task steps in workflows to target multiple GitHub repositories simultaneously, significantly increasing workflow flexibility."},{"number":126226,"tier":"substantive","P":null,"summary":"Adds API, Node.js and Python tabs to the transactional email snippet so users can copy SDK setup code directly."},{"number":126304,"tier":"routine","P":null,"summary":"Adds a team_capped label to the email queue-to-send metric so on-call can filter deliberate cap waits from slow workers."},{"number":126479,"tier":"routine","P":null,"summary":"Appends the AI task token to the workflow step's wait log so the 'View task' link appears for all AI task steps."},{"number":127335,"tier":"substantive","P":null,"summary":"Workflow editor now loads existing schedules for any trigger, fixing duplicate schedule firings when a workflow switches back to a schedule trigger."},{"number":127358,"tier":"substantive","P":null,"summary":"Deletes stale workflow schedules when the live trigger leaves schedule, preventing duplicate workflow runs on each occurrence."},{"number":127579,"tier":"substantive","P":null,"summary":"Workflows now hold frequency-capped messages until a cap slot frees instead of skipping them, with a new held-send metric."},{"number":127592,"tier":"substantive","P":3.65,"summary":"Adds a nullable marketing_frequency_cap_hold_hours setting (1–168) across the workflows config model, migration, serializers, settings UI and generated types, laying the schema groundwork for a separate worker PR that actually holds capped marketing messages."},{"number":128343,"tier":"substantive","P":null,"summary":"Adds a warning banner across workflow email metric surfaces flagging the Nov 3 incident window where metrics are wrong."}]},{"id":"ws2","title":"Product: Messaging · messaging","area":"Product: Messaging","agg":{"prs_n":38,"deepread_n":3,"tier_counts":{"major":7,"routine":14,"substantive":17},"points_sum":149.7,"L_mean":1.67,"Q_mean":2,"span_days":79,"lines":13503},"prs":[{"number":83456,"tier":"major","P":null,"summary":"Push registration without an integration now returns 200 instead of 400, ending a daily paging incident and stopping SDK retry loops."},{"number":83466,"tier":"major","P":5.92,"summary":"Push subscription registration without a configured firebase/apns integration now returns 200 with stored/push_enabled false instead of 400, removing a fleet-wide error floor that paged infra and tripped SDK retry logic, while still not storing tokens and preserving DELETE $unset behavior."},{"number":83501,"tier":"routine","P":null,"summary":"Adds per-field detail (absent/empty/invalid) to push subscription rejection logs, improving internal debugging without changing responses."},{"number":113876,"tier":"substantive","P":null,"summary":"Introduces a messaging facade and moves outside callers onto it, unblocking a CI test-skip seal; no user-visible change."},{"number":113890,"tier":"routine","P":null,"summary":"Seals 9 reverse accessors on Team/User in messaging models via a no-op migration to enforce facade isolation; no user-visible or SQL change."},{"number":113926,"tier":"routine","P":null,"summary":"Moves the recipient preferences page, views and templates from core into the messaging product with no behavior change."},{"number":113944,"tier":"routine","P":null,"summary":"Moves messaging API code into presentation/views and seals the tach import boundary; no user-visible behavior change."},{"number":113968,"tier":"routine","P":null,"summary":"Moves messaging suppression-list queries behind the facade with no behavior change, advancing the CI-skip refactor."},{"number":113996,"tier":"routine","P":null,"summary":"Moves the messaging opt-out API behind the facade with no behavior change, as one slice of a larger migration."},{"number":114009,"tier":"routine","P":null,"summary":"Moves the messaging recipient preferences page behind the facade with no behavior change, completing Lane C's import cleanup."},{"number":114021,"tier":"routine","P":null,"summary":"Moves Customer.io sync setup writes from messaging views into a facade and service, with no user-visible behavior change."},{"number":114025,"tier":"routine","P":null,"summary":"Moves the Customer.io webhook logic behind the messaging facade with no behavior change, as part of a larger migration track."},{"number":114034,"tier":"routine","P":null,"summary":"Moves messaging message-category CRUD behind a facade, removing the model-backed viewset with no user-visible behavior change."},{"number":114069,"tier":"substantive","P":null,"summary":"Moves messaging template library behind a facade and seals the product so messaging PRs run only messaging tests instead of the full suite."},{"number":117670,"tier":"substantive","P":null,"summary":"Adds an endpoint to make a message template transactional by creating and linking a workflow; flagged, sends nothing yet."},{"number":117785,"tier":"major","P":5.92,"summary":"On saving a transactional message template, this PR writes the template's content as a new version of its backing workflow inside a row-locked transaction, rejects edits that would stop it sending, enforces workflow editor access, and unlinks the template when its workflow is deleted."},{"number":117786,"tier":"substantive","P":null,"summary":"Adds a POST send endpoint that runs a transactional email template's workflow via cdp-api, returning a message_id."},{"number":117973,"tier":"substantive","P":null,"summary":"Restores stylesheet loading on messaging preference, unsubscribe and error pages that rendered unstyled due to a hashed static path 404."},{"number":120327,"tier":"substantive","P":null,"summary":"Fixes email templates silently dropping the preheader on save, so transactional sends now include preview text."},{"number":120392,"tier":"substantive","P":null,"summary":"Adds an optional Idempotency-Key header to the transactional email send API so callers can retry safely without duplicate sends."},{"number":120520,"tier":"major","P":null,"summary":"Adds a per-template 'Protect sensitive data' switch that redacts email bodies, subjects and link query strings from stored emails, events and snapshots to prevent secret leakage."},{"number":120559,"tier":"routine","P":null,"summary":"Adds a nullable-defaulted `sensitive` boolean column to MessageTemplate via migration, with no behavior until the stacked PR lands."},{"number":121871,"tier":"major","P":9.85,"summary":"Adds a per-template sender (custom name/address) and reply-to to transactional email templates, storing the sender on conversion and copying it into the hidden workflow on publish, with domain/format validation and legacy-content handling."},{"number":123019,"tier":"substantive","P":null,"summary":"Transactional email sends now return explicit 422 refusals instead of false 202 success when suppressed, paused, or suspended, preventing silent non-delivery."},{"number":123492,"tier":"substantive","P":null,"summary":"Fixes suppression logic so transactional email (password resets, login notices) is no longer silently dropped for spam-complaint addresses."},{"number":123556,"tier":"substantive","P":null,"summary":"Adds a new /messaging/send/email/ endpoint as the cross-SDK contract for sending transactional email, sharing logic via a mixin."},{"number":123878,"tier":"substantive","P":null,"summary":"Transactional email API now rejects unreachable recipients with 422 instead of falsely returning 202 queued, sharing validation with the worker."},{"number":123932,"tier":"substantive","P":null,"summary":"Adds a GET endpoint to read transactional email delivery status by message id, with project secret key auth and dedicated rate limits."},{"number":124385,"tier":"major","P":null,"summary":"Implements a new asynchronous API for importing messaging provider steps, resolving synchronous timeout issues during migration from c.io to Workflows."},{"number":124425,"tier":"routine","P":null,"summary":"Adds a team-scoped ProviderImportRun model and migration to persist background import progress; no code reads or writes it yet."},{"number":124426,"tier":"substantive","P":null,"summary":"Adds a Temporal workflow to run messaging provider imports asynchronously with resumable, idempotent steps, though no user-facing API triggers it yet."},{"number":124696,"tier":"substantive","P":null,"summary":"Adds a ClickHouse email_status table, Kafka pipeline and materialized view to track transactional email lifecycle per message for a new messaging feature."},{"number":125066,"tier":"substantive","P":null,"summary":"Adds transactional email and SES latency/error metrics across Django and CDP to give on-call visibility into send timing and failures."},{"number":125312,"tier":"routine","P":null,"summary":"Adds analytics capture of transactional email status reads to measure adoption of the existing lookup endpoint."},{"number":125415,"tier":"major","P":null,"summary":"A new guided skill is added to proactively help users set up and configure transactional email services like Resend and Postmark."},{"number":125444,"tier":"substantive","P":null,"summary":"Transactional email API now returns 202 without awaiting Kafka telemetry acks, cutting ~900ms p50 send latency."},{"number":126287,"tier":"routine","P":null,"summary":"Flattens the transactional email send API body to top-level template_id/distinct_id while keeping the nested shape as a fallback for released SDKs."},{"number":128014,"tier":"substantive","P":null,"summary":"One-click unsubscribe GET links now show a confirm page instead of opting users out, so link scanners no longer silently unsubscribe email recipients."}]},{"id":"ws3","title":"Django platform (API/models/auth) · email","area":"Django platform (API/models/auth)","agg":{"prs_n":13,"deepread_n":2,"tier_counts":{"substantive":8,"routine":3,"major":2},"points_sum":57.27,"L_mean":1.5,"Q_mean":2,"span_days":73,"lines":3708},"prs":[{"number":82736,"tier":"substantive","P":null,"summary":"Adds shared scoped service-to-service JWT machinery in Python and Node, replacing hand-rolled INTERNAL_API_SECRET auth; dormant with no consumer yet."},{"number":84546,"tier":"routine","P":3.65,"summary":"Adds a kind-gated mapping of Meta Graph error code 190 to invalid_grant in the OAuth refresh failure classifier so revoked Meta/Instagram tokens land in the correct alert bucket instead of `other`, with new parameterized tests and guard rows."},{"number":91668,"tier":"major","P":null,"summary":"Adds a purpose-scoped media library and presigned upload flow, allowing agents to upload and reuse images directly for tasks like email templates."},{"number":93202,"tier":"substantive","P":null,"summary":"Canvas agents can now list, upload and reuse public images via the shared media library, adding a canvas media purpose."},{"number":98531,"tier":"routine","P":null,"summary":"Skips DEBUG-mode response validation for PolymorphicProxySerializer so local dev endpoints return 200 instead of 500; production unaffected."},{"number":122019,"tier":"major","P":9.62,"summary":"Adds per-recipient, flag-gated routing of PostHog's transactional emails through Workflows with idempotency-keyed retries and a Customer.io fallback, starting with password_reset, to enable a gradual migration off Customer.io."},{"number":122502,"tier":"substantive","P":null,"summary":"Maps all 35 transactional email templates to Workflows template ids, enabling flag-based migration off Customer.io without deploys."},{"number":123060,"tier":"routine","P":null,"summary":"Passes the instance region to the transactional-email workflows flag so US and EU can roll out separately; no behavior change until flag conditions use it."},{"number":123308,"tier":"substantive","P":null,"summary":"Fixes app metrics trend charts dropping the first partial bucket, so workflow and destination metric counts now include all rows in range."},{"number":123938,"tier":"substantive","P":null,"summary":"Retries transactional email sends (invites, password resets, alerts) when a transient database error occurs instead of silently dropping them."},{"number":124613,"tier":"substantive","P":null,"summary":"Drops transactional emails Workflows refuses as unreachable, avoiding futile retries, false exceptions, and sender-reputation damage."},{"number":124631,"tier":"substantive","P":null,"summary":"Stops inline email sends from blocking signup/login responses on a cross-region analytics flush, speeding up auth requests."},{"number":125322,"tier":"substantive","P":null,"summary":"Reworks transactional email routing so suppressed recipients are dropped and other failures retry on Workflows instead of silently falling back to Customer.io, making the provider kill switch real."}]},{"id":"ws4","title":"Product: CDP · cdp","area":"Product: CDP","agg":{"prs_n":10,"deepread_n":0,"tier_counts":{"routine":2,"substantive":6,"major":2},"points_sum":44,"L_mean":null,"Q_mean":null,"span_days":81,"lines":2420},"prs":[{"number":78204,"tier":"routine","P":null,"summary":"CDP email input validator now reports all missing keys in a single error instead of one per round trip."},{"number":81705,"tier":"substantive","P":null,"summary":"Fixes Salesforce CDP templates: corrects wrong default object name, rejects empty path segments, and improves error messages for update steps."},{"number":81732,"tier":"substantive","P":null,"summary":"Adds a Salesforce lookup CDP step that returns match results as output variables, enabling read-before-write workflow branches."},{"number":85712,"tier":"substantive","P":null,"summary":"CDP re-runs of disabled functions now fail visibly with a terminal error row and a 400 on /rerun, instead of getting stuck running forever."},{"number":86537,"tier":"substantive","P":null,"summary":"Adds an operator command to mark stuck CDP runs as failed, restoring re-run buttons and enabling bulk replay."},{"number":86614,"tier":"substantive","P":null,"summary":"Removes a CDP queryset filter that hid hog functions filtered on all events, restoring list, retrieve and update visibility for users."},{"number":86989,"tier":"major","P":null,"summary":"Adds a flagged banner letting owners of destinations that lost credentials re-enter secrets and replay failed sends before data is dropped."},{"number":115434,"tier":"substantive","P":null,"summary":"Routes seven sealed-product views through cdp presentation re-exports to satisfy the presentation-facade contract, advancing product isolation."},{"number":115474,"tier":"major","P":null,"summary":"Moves destination templates and tests from a shared core directory to the product-specific CDP backend directory for improved code organization."},{"number":123306,"tier":"routine","P":null,"summary":"Fixes misleading cohort filter error messages in CDP by removing the wrong internal-user settings link and clarifying wording."}]},{"id":"ws5","title":"Product: Desktop · desktop","area":"Product: Desktop","agg":{"prs_n":9,"deepread_n":0,"tier_counts":{"substantive":7,"major":2},"points_sum":44,"L_mean":null,"Q_mean":null,"span_days":59,"lines":70236},"prs":[{"number":90109,"tier":"substantive","P":null,"summary":"Keeps Slack-triggered workflow AI task runs open so the agent can post its reply and continue the thread conversation."},{"number":93173,"tier":"substantive","P":null,"summary":"Regenerates the desktop API client via a new allowlist-based, prettier-formatted generator and adapts code to the fresher types."},{"number":93225,"tier":"substantive","P":null,"summary":"Reworks desktop Loops list, detail and form to back onto the workflows engine behind a flag, unifying scheduling and adding team-skills picker."},{"number":97297,"tier":"substantive","P":null,"summary":"Command center task composer now shows a space chip so new tasks file into the chosen space instead of always #me."},{"number":98512,"tier":"major","P":null,"summary":"Enables the creation of workflow-backed loops in PostHog Desktop using a new building-loops skill, unlocking complex automation capabilities."},{"number":100279,"tier":"substantive","P":null,"summary":"Scopes the desktop Personal space Loops tab to only its own loops, fixing loops leaking into everyone's Personal space."},{"number":102367,"tier":"major","P":null,"summary":"Adds a new native iOS PostHog mobile app for cloud tasks, reports, offline reading, and mobile chat."},{"number":107776,"tier":"substantive","P":null,"summary":"Adds keyboard shortcuts to open Command Center and step through desktop rail destinations, with shared navigation logic and analytics."},{"number":123289,"tier":"substantive","P":null,"summary":"Adds ph.tools support so PostHog Desktop canvas boards can run MCP tool calls, matching web behavior behind a feature flag."}]},{"id":"ws6","title":"Product: Tasks · tasks","area":"Product: Tasks","agg":{"prs_n":8,"deepread_n":0,"tier_counts":{"substantive":7,"major":1},"points_sum":36,"L_mean":null,"Q_mean":null,"span_days":69,"lines":1614},"prs":[{"number":88254,"tier":"substantive","P":null,"summary":"Adds daily rate limits and AI-usage gating to workflow-created AI tasks to prevent runaway paid agent runs and quota exhaustion."},{"number":90304,"tier":"substantive","P":null,"summary":"Workflow AI task runs without a Slack thread now end when the agent finishes, freeing sandboxes instead of idling."},{"number":98358,"tier":"substantive","P":null,"summary":"Fixes workflow-fired task runs that died mid-turn being recorded as completed, holding the idle window open and surfacing failures."},{"number":99007,"tier":"substantive","P":null,"summary":"Workflows can now file their AI tasks in a space, so the space's feed shows the runs."},{"number":113499,"tier":"substantive","P":null,"summary":"Fixes empty final messages in Tasks workflow steps when the agent ends with finish, so Slack steps post the full report."},{"number":119414,"tier":"major","P":null,"summary":"Fixes silent workflow timeouts by explicitly stopping tasks when AI credits are exhausted, providing clear error messages instead of hanging."},{"number":119417,"tier":"substantive","P":null,"summary":"Adds a terminal task-run status counter with rich labels so silent workflow failures become alertable, closing a monitoring gap."},{"number":126478,"tier":"substantive","P":null,"summary":"The agent `finish` tool now accepts an optional report and sends it as the run's final message, fixing null outputs in post-task workflow steps."}]},{"id":"ws7","title":"Background jobs (Temporal/Celery/Dagster) · weekly-digest","area":"Background jobs (Temporal/Celery/Dagster)","agg":{"prs_n":4,"deepread_n":0,"tier_counts":{"substantive":4},"points_sum":16,"L_mean":null,"Q_mean":null,"span_days":4,"lines":709},"prs":[{"number":124322,"tier":"substantive","P":null,"summary":"Adds a report-only usage field counting transactional workflow emails, giving the Workflows team visibility into API-triggered sends without changing billing."},{"number":124980,"tier":"substantive","P":null,"summary":"Routes weekly digest emails through a Workflows webhook behind a flag, migrating from Customer.io with auth, idempotency, and rate limiting."},{"number":127219,"tier":"substantive","P":null,"summary":"Fixes weekly digest webhook posting by JSON-encoding the payload, keeping failed orgs unsent, and using user UUIDs for idempotency keys."},{"number":127259,"tier":"substantive","P":null,"summary":"Adds an ops command to resend weekly digest emails to chosen orgs, with Workflows-only routing and correct digest period."}]},{"id":"misc","title":"杂项（含 14 条实质及以上）","area":"mixed","agg":{"prs_n":34,"deepread_n":2,"tier_counts":{"substantive":11,"routine":4,"major":3,"mechanical":16},"points_sum":78.44,"L_mean":1.5,"Q_mean":2,"span_days":83,"lines":9743},"prs":[{"number":78185,"tier":"substantive","P":null,"summary":"Stamps machine-readable error code and normalized field path on failed MCP tool calls so failure modes can be grouped in analytics."},{"number":78191,"tier":"substantive","P":null,"summary":"Fixes two bugs where invalid user input in feature flag filters caused opaque 500 errors, replacing them with informative 400 Bad Request responses."},{"number":78209,"tier":"routine","P":null,"summary":"Unsupported warehouse join key expressions now raise an exposed QueryError with an actionable message instead of an opaque internal 500."},{"number":78879,"tier":"substantive","P":null,"summary":"Steers MCP agents to design-first email templates and hides the html field, plus fixes a codegen exclusion walker bug affecting several tools."},{"number":87020,"tier":"routine","P":null,"summary":"Fixes internal local Slack dev setup: ngrok domain matching, manifest subscription, and docs warnings for developers."},{"number":87669,"tier":"substantive","P":null,"summary":"Adds a JWT-only internal conversations ticket route with team/ticket pinning and a cutover metric, replacing the deprecated secret_api_token path."},{"number":100361,"tier":"substantive","P":null,"summary":"Warehouse webhook sources now accept-and-drop unverifiable deliveries instead of rejecting them, surfacing the setup gap in the UI."},{"number":101799,"tier":"major","P":null,"summary":"Adds a substring pre-check to HogQL person property filters, roughly doubling speed and cutting CPU for large teams."},{"number":102336,"tier":"substantive","P":null,"summary":"Retires legacy loops MCP tools when workflows back loops, preventing agents from creating invisible loops in Desktop."},{"number":109022,"tier":"mechanical","P":null,"summary":"Moves secret input helpers out of the workflows view into a service and facade, with no behavior change."},{"number":109409,"tier":"mechanical","P":null,"summary":"Moves 28 workflow-tasks endpoint test cases from the tasks product into the workflows product, with no production code changes."},{"number":115422,"tier":"routine","P":null,"summary":"Adds products/cdp paths to the Node CI filters and a semgrep exemption so upcoming file moves keep their checks."},{"number":115427,"tier":"mechanical","P":null,"summary":"Moves ClickHouse table definitions for hog_invocation_results and message_assets into their product modules with no behavior change."},{"number":115433,"tier":"mechanical","P":null,"summary":"Moves hog invocation serializers and ClickHouse reads from posthog/api into products/cdp with no behavior change."},{"number":115435,"tier":"mechanical","P":null,"summary":"Moves posthog/cdp/internal_events.py into products/cdp/backend and updates its 23 importers and patch targets; a pure module relocation."},{"number":115436,"tier":"mechanical","P":null,"summary":"Moves CDP hog validation, filters and filter_globals.json from posthog/cdp into products/cdp/backend, updating imports and patch targets with no behavior change."},{"number":115445,"tier":"mechanical","P":null,"summary":"Moves remaining CDP helper modules and their tests from posthog/cdp into products/cdp with no behavior change."},{"number":115473,"tier":"mechanical","P":null,"summary":"Moves the hog function template dataclass module into products/cdp with a re-export shim, no behavior change."},{"number":115475,"tier":"mechanical","P":null,"summary":"This PR moves destination template directories from posthog/cdp/templates to products/cdp/backend/templates to standardize the codebase structure."},{"number":115476,"tier":"mechanical","P":null,"summary":"Rewrites import paths for HogFunctionTemplateDC across 29 warehouse source files; only import lines change, no behavior."},{"number":115477,"tier":"mechanical","P":null,"summary":"Rewrites import paths for warehouse source webhook template dataclasses to import from products/cdp; only import lines change."},{"number":115478,"tier":"mechanical","P":null,"summary":"Updates import paths for CDP template dataclasses across fourteen mostly-test callers; only import lines change."},{"number":115581,"tier":"mechanical","P":null,"summary":"Removes the fully-rolled-out github-workflow-triggers feature flag gate and its test, with no behavior change for users."},{"number":116087,"tier":"mechanical","P":null,"summary":"Moves the CDP template registry from posthog/cdp into products/cdp/backend/templates, rewriting import paths with no definition or behavior changes."},{"number":116171,"tier":"mechanical","P":null,"summary":"Removes stale posthog/cdp/ path references from CI filters, semgrep exemptions, ownership rules and comments after the directory move."},{"number":117019,"tier":"routine","P":null,"summary":"Reloads the cohorts list and allCohorts after a refused cohort delete so the cohort reappears instead of staying hidden."},{"number":117887,"tier":"substantive","P":null,"summary":"Adds Today highlights surfacing workflow health (email suspension, failures) and pending suggestions for owned workflows, giving users proactive visibility on failures."},{"number":118431,"tier":"substantive","P":null,"summary":"Adds an agent skill that turns a JSON storyboard into branded, narrated demo videos of the local app, reusable by the team."},{"number":118434,"tier":"substantive","P":4.81,"summary":"Propagates the backfill `origin` through cascaded cohort membership changes (while deliberately leaving `run_id` unset) so the cohort trigger consumer skips spurious workflow re-triggers caused by backfills, with regression tests covering both the emitted change and the onward cascade."},{"number":119415,"tier":"substantive","P":null,"summary":"Adds zoom framing and a realistic pointer to the demo-video recording skill, and fixes video truncation and blank-frame issues."},{"number":120056,"tier":"substantive","P":null,"summary":"Adds an MCP tool letting agents make email templates transactional, with typed confirmation and warnings that the change is irreversible."},{"number":121092,"tier":"major","P":null,"summary":"Fixes realtime composed cohorts being stamped ready with zero members, which made flags, workflows and triggers silently match nobody."},{"number":123064,"tier":"major","P":9.62,"summary":"Adds a general ph.tools path so canvases can run allowlisted PostHog MCP tools (e.g. read and set a feature flag rollout) as the viewer, with capability declaration, scope checks, throttling and explicit refusal/error mapping."},{"number":123298,"tier":"mechanical","P":null,"summary":"Removes the always-on workflows-email-media-library feature flag and its dead code path; no user-visible change."}]}];
